import type { LayerType } from "./enums";
import type { AssetId, LayerId } from "./ids";

export interface ITransform2D {
  x: number;
  y: number;
  scaleX: number;
  scaleY: number;
  rotation: number;
  anchorX: number;
  anchorY: number;
}

/**
 * Common fields for every Layer. See GLOSSARY.md "Layer" — the canonical
 * unit of "what", independent of Timeline (when) and Rendering (where in
 * the frame). Referenced by TrackItems by id, never embedded/duplicated.
 */
export interface ILayerBase {
  id: LayerId;
  type: LayerType;
  name: string;
  transform: ITransform2D;
  opacity: number;
  visible: boolean;
  locked: boolean;
  /** Composition Graph parent, or null at the root. See ADR-006. */
  parentId: LayerId | null;
}

export interface IVideoLayer extends ILayerBase {
  type: LayerType.Video;
  assetId: AssetId;
  playbackRate: number;
}

export interface IImageLayer extends ILayerBase {
  type: LayerType.Image;
  assetId: AssetId;
  fitMode: "contain" | "cover" | "fill" | "none";
}

export interface IAudioLayer extends ILayerBase {
  type: LayerType.Audio;
  assetId: AssetId;
  volume: number;
}

export interface ITextLayer extends ILayerBase {
  type: LayerType.Text;
  content: string;
  fontFamily: string;
  fontSize: number;
  color: string;
  textAlign: "left" | "center" | "right";
}

export interface IStickerLayer extends ILayerBase {
  type: LayerType.Sticker;
  assetId: AssetId;
}

export interface IShapeLayer extends ILayerBase {
  type: LayerType.Shape;
  shape: "rectangle" | "ellipse" | "polygon" | "star" | "path";
  fillColor: string;
  strokeColor: string;
  strokeWidth: number;
  cornerRadius: number;
}

export interface IGroupLayer extends ILayerBase {
  type: LayerType.Group;
  /** Composition Graph children, in render order. */
  childIds: LayerId[];
}

export type ILayer =
  IVideoLayer | IImageLayer | IAudioLayer | ITextLayer | IStickerLayer | IShapeLayer | IGroupLayer;

/**
 * Layers whose properties the Animation Engine (Phase 6,
 * `AnimatablePropertyRegistry`) may attach keyframe tracks to. Every
 * current layer type qualifies today — `transform` and `opacity` on
 * `ILayerBase` are the baseline animatable surface for all of them. Kept
 * as its own alias (rather than reusing `ILayer` at call sites) so a
 * future layer type that opts out doesn't require touching every
 * consumer that only cares "is this animatable".
 */
export type IAnimatableLayer = ILayerBase;

/** See docs/08-layer-engine/overview.md */
export enum LayerType {
  Video = "Video",
  Image = "Image",
  Audio = "Audio",
  Text = "Text",
  Sticker = "Sticker",
  Shape = "Shape",
  Group = "Group",
}

/** See docs/07-timeline-engine/tracks.md */
export enum TrackType {
  Video = "Video",
  Audio = "Audio",
  Text = "Text",
  Shape = "Shape",
  Sticker = "Sticker",
  Camera = "Camera",
  Guide = "Guide",
  Adjustment = "Adjustment",
  Effect = "Effect",
}

export enum PlaybackState {
  Idle = "Idle",
  Playing = "Playing",
  Paused = "Paused",
  Seeking = "Seeking",
}

/** See docs/06-animation-engine/interpolation.md */
export enum InterpolationType {
  Linear = "Linear",
  Bezier = "Bezier",
  Step = "Step",
}

/** See docs/06-animation-engine/property-system.md */
export enum PropertyValueType {
  Number = "Number",
  Vector2 = "Vector2",
  Vector3 = "Vector3",
  Color = "Color",
  Boolean = "Boolean",
  Text = "Text",
  Gradient = "Gradient",
  Matrix = "Matrix",
}

/** See docs/05-rendering-engine/overview.md (ADR-004) */
export enum RenderBackend {
  WebGPU = "WebGPU",
  WebGL2 = "WebGL2",
  Canvas2D = "Canvas2D",
  Software = "Software",
}

/** Single MVP preset per docs/24-roadmap/mvp.md Step 1. Extend as new presets ship. */
export enum ExportPreset {
  Preset1080p30H264Opus = "1080p30-h264-opus",
}

/** See docs/13-export/overview.md job state machine */
export enum ExportJobStatus {
