1	import { DEFAULT_TICK_RESOLUTION, PlaybackState, toTick, type Tick } from "@motion-studio/shared";
2	
3	export interface IPlayheadLoop {
4	  inTick: Tick;
5	  outTick: Tick;
6	}
7	
8	/**
9	 * The Timeline's tick-based playhead: current position, loop in/out points,
10	 * and frame-stepping, always in integer Ticks (CLAUDE.md "Canonical
11	 * names"). Deliberately does not run its own raf loop — Core's `Scheduler`
12	 * (Phase 2) already owns wall-clock-to-tick timing; a driver (the Editor
13	 * Service, wiring Scheduler's `onTimelineUpdate` handler) calls `advance()`
14	 * with the tick delta each frame. This keeps Timeline ignorant of wall-clock
15	 * time, per the engine ownership table in ARCHITECTURE.md §3.
16	 */
17	export class Playhead {
18	  private tick: Tick = toTick(0);
19	  private state: PlaybackState = PlaybackState.Idle;
20	  private loop: IPlayheadLoop | null = null;
21	
22	  constructor(
